  function peoplePersonPage(d) {
    const p = page(d.id, d.title, d.lead, 'people');
    p.status = 'ДОСЬЕ';
    p.category = d.group; // Будущий фильтр можно сделать без переписывания карточек.
    p.blocks = [
      ...d.scenes.map((s,i) => ({ id:'history-'+(i+1), heading:s.heading, text:s.text })),
      { id:'connections', heading:'Связи', text:d.connections },
      { id:'questions', heading:'Открытые вопросы', text:d.questions || 'Пока нет отдельного вопроса.' }
    ];
    return p;
  }

  peopleDossiers.forEach(d => {
    const key = 'people/' + d.id;
    if (!art.pageImages[key]) art.pageImages[key] = { card:'assets/people.png', cover:'assets/people.png', wide:'assets/people.png' };
  });

